# Compares median-based vs mean-based metrics under 5%/10% winsorization.

import json
import numpy as np
from scipy import stats
from scipy.stats.mstats import winsorize as scipy_winsorize
from pathlib import Path
from collections import defaultdict

BASE = Path("/root/autodl-tmp/pacs")
OUT = BASE / "analysis_output"
OUT.mkdir(exist_ok=True)

MODELS = {"deepseek": "ds", "qwen": "qw"}
STRATEGIES = ["imp", "rand"]
SPARSITIES = ["s015", "s020", "s025", "s030"]
SP_KEY = {"s015": "0.15", "s020": "0.2", "s025": "0.25", "s030": "0.3"}
PHASES = ["high", "mid", "low"]
B_BOOT = 10000
SEED = 42
rng = np.random.RandomState(SEED)


def load_per_problem(model_short, strategy, slabel):
    d = BASE / f"profiling_output_n500_bf16_{model_short}_{strategy}_{slabel}" / "profiling_results.json"
    if not d.exists():
        return None
    data = json.load(open(d))
    pp = data.get("per_problem_ii", {})
    k = SP_KEY[slabel]
    return pp.get(k, pp.get(list(pp.keys())[0], []))


def get_diffs(problems):
    diffs, ids = [], []
    for p in problems:
        lo, hi = p.get("ii_low"), p.get("ii_high")
        if lo is not None and hi is not None:
            diffs.append(lo - hi)
            ids.append(p.get("problem_id", ""))
    return np.array(diffs), ids


def get_paired_phase_vals(problems):
    lows, highs = [], []
    for p in problems:
        lo, hi = p.get("ii_low"), p.get("ii_high")
        if lo is not None and hi is not None:
            lows.append(lo)
            highs.append(hi)
    return np.array(lows), np.array(highs)


def get_phase_vals(problems, phase):
    vals, ids = [], []
    for p in problems:
        v = p.get(f"ii_{phase}")
        if v is not None:
            vals.append(v)
            ids.append(p.get("problem_id", ""))
    return np.array(vals), ids


def win(arr, pct):
    return np.array(scipy_winsorize(arr, limits=[pct, pct]))


def bootstrap_median_ci(arr, B=B_BOOT, alpha=0.05):
    n = len(arr)
    boots = np.array([np.median(arr[rng.randint(0, n, n)]) for _ in range(B)])
    return float(np.percentile(boots, 100*alpha/2)), float(np.percentile(boots, 100*(1-alpha/2)))


def bootstrap_mean_ci(arr, B=B_BOOT, alpha=0.05):
    n = len(arr)
    boots = np.array([np.mean(arr[rng.randint(0, n, n)]) for _ in range(B)])
    return float(np.percentile(boots, 100*alpha/2)), float(np.percentile(boots, 100*(1-alpha/2)))


